const defaultLogger = {
  debug: (msg: string, meta?: Record<string, unknown>) => console.debug(`[test-intelligence] ${msg}`, meta),
  info: (msg: string, meta?: Record<string, unknown>) => console.info(`[test-intelligence] ${msg}`, meta),
